-- Nova versão dos exemplos resolvidos de Drogas (Lei 11.343/2006) e Armas (Lei 10.826/2003).
-- 6 casos concretos por lei, conferidos no Planalto em 08/10/2026 (inclui art. 40-A da Lei de Drogas e art. 21-A
-- do Estatuto, ambos incluídos pela Lei 15.358/2026). Mesmo conteúdo para cada material que trata da lei.
-- Entra `under_review`: as versões anteriores continuam visíveis até o admin ativar estas no painel
-- (Biblioteca). Não define reviewed_by/reviewed_at. Materiais que não existirem no banco são ignorados.
begin;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei de Drogas", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["É consumo pessoal ou outra finalidade? (art. 28 × art. 33)", "Qual verbo e qual papel: traficante, financiador ou informante? (arts. 33, 36, 37)", "Há associação estável? (art. 35)", "A pena sofre redução (§ 4º) ou aumento (arts. 40 e 40-A)?"]}], "cases": [{"id": "drog-1", "title": "Mesma droga no bolso: consumo ou tráfico?", "scenario": "João foi abordado com uma pequena porção de droga e disse que era para uso próprio. Ana foi abordada com uma porção parecida, mas tinha balança, embalagens e mensagens combinando entregas.", "question": "João e Ana respondem pelo mesmo crime?", "steps": ["O art. 28 pune quem adquire, guarda, tem em depósito, transporta ou traz consigo droga PARA CONSUMO PESSOAL. As penas são advertência, prestação de serviços à comunidade e medida educativa: não há pena de prisão.", "O art. 33 pune quem, entre muitos verbos (como vender, oferecer, guardar, transportar e trazer consigo), pratica a conduta sem a finalidade de consumo próprio. A pena é reclusão de 5 a 15 anos e 500 a 1.500 dias-multa.", "Os verbos \"guardar\" e \"trazer consigo\" aparecem nos dois artigos. O que separa os crimes é a finalidade (consumo pessoal ou não), que se prova pelas circunstâncias do caso."], "conclusion": "Em tese, João responde pelo art. 28 e Ana pelo art. 33. A finalidade, mostrada por balança, embalagens e mensagens, é o que muda o enquadramento.", "variation": {"scenario": "E se João estivesse com a mesma porção, mas com mensagens combinando a venda para outras pessoas?", "answer": "A finalidade de consumo pessoal fica afastada pelos indícios, e o fato pode ser analisado como art. 33."}, "pitfall": "Decorar só o verbo. \"Guardar\" e \"trazer consigo\" existem nos dois artigos; a finalidade é que decide.", "articles": ["Art. 28", "Art. 33"]}, {"id": "drog-2", "title": "Guardar a droga dos outros também é tráfico", "scenario": "Marta nunca vendeu nada. A pedido de um conhecido, ela deixa uma caixa com drogas guardada no quarto dos fundos da casa dela e recebe um valor por mês.", "question": "Marta só comete crime se vender a droga?", "steps": ["O art. 33 lista muitos verbos: importar, exportar, remeter, preparar, produzir, fabricar, adquirir, vender, expor à venda, oferecer, ter em depósito, transportar, trazer consigo, guardar, prescrever, ministrar, entregar a consumo ou fornecer.", "\"Ter em depósito\" e \"guardar\" estão na lista. Marta não precisa vender para se enquadrar.", "A pena é a mesma do caput: reclusão de 5 a 15 anos e 500 a 1.500 dias-multa."], "conclusion": "Não é preciso vender. Guardar ou ter em depósito drogas, sem autorização, já se encaixa no art. 33. Marta responde em tese pelo tráfico.", "variation": {"scenario": "E se Marta guardasse a caixa sem saber que havia drogas dentro?", "answer": "Sem conhecimento do conteúdo, falta o dolo exigido para o crime. A prova do que ela sabia é decisiva."}, "pitfall": "Achar que traficante é só quem vende. O art. 33 é um tipo de conduta múltipla: vários verbos, um mesmo crime.", "articles": ["Art. 33"]}, {"id": "drog-3", "title": "Tráfico privilegiado: todos os requisitos juntos", "scenario": "Lucas foi condenado por tráfico. É primário, tem bons antecedentes e não participa de nenhuma organização criminosa. Já Beto, também condenado, é primário e de bons antecedentes, mas integra uma organização criminosa.", "question": "Os dois podem ter a pena reduzida pelo art. 33, § 4º?", "steps": ["O § 4º permite reduzir a pena de 1/6 a 2/3 nos delitos do caput e do § 1º, desde que o agente seja primário, de bons antecedentes, não se dedique a atividades criminosas e não integre organização criminosa.", "Os requisitos são cumulativos: falhou um, falha a redução.", "Lucas cumpre os requisitos citados. Beto integra organização criminosa, e isso afasta a redução."], "conclusion": "Lucas pode ter a redução; Beto não. A redução é de 1/6 a 2/3 e é aplicada pelo juiz conforme o caso.", "variation": {"scenario": "E se Beto saísse da organização antes do crime e comprovasse isso?", "answer": "O requisito é não integrar organização criminosa na época do fato. A prova da situação real de Beto é que decide."}, "pitfall": "Achar que a redução é automática para réu primário. É preciso cumprir todos os requisitos juntos.", "articles": ["Art. 33"]}, {"id": "drog-4", "title": "Associação para o tráfico: duas pessoas bastam?", "scenario": "Dois amigos combinam comprar droga juntos e revendê-la durante meses, dividindo as tarefas e o lucro.", "question": "Eles respondem também pelo art. 35?", "steps": ["O art. 35 pune \"associarem-se duas ou mais pessoas para o fim de praticar, reiteradamente ou não,\" os crimes dos arts. 33, caput e § 1º, e 34. A pena é reclusão de 3 a 10 anos e 700 a 1.200 dias-multa.", "O número mínimo é de 2 pessoas (na Lei 12.850 são 4; na definição de facção da Lei 15.358, 3).", "Os dois se uniram com o fim de traficar, e a união durou meses. Os tribunais entendem que a associação exige vínculo estável e permanente, e aqui ele existe."], "conclusion": "Sim. Em tese há associação para o tráfico (art. 35), somada ao tráfico do art. 33, porque o acordo era para traficar de forma estável.", "variation": {"scenario": "E se os dois amigos apenas combinassem, uma única vez, de comprar e vender uma porção?", "answer": "A lei diz \"reiteradamente ou não\", mas os tribunais exigem estabilidade e permanência do vínculo. Um ajuste ocasional costuma ser tratado como concurso de pessoas no art. 33, e não como associação. Confira a jurisprudência atual."}, "pitfall": "Misturar os números mínimos: 2 pessoas (art. 35 da Lei de Drogas), 3 (facção, Lei 15.358) e 4 (organização criminosa, Lei 12.850).", "articles": ["Art. 35"]}, {"id": "drog-5", "title": "Quem paga e quem avisa: arts. 36 e 37", "scenario": "Caio paga a compra de um carregamento de droga, sem nunca tocar nela. Dani, de 20 anos, fica na esquina e avisa por rádio quando a polícia se aproxima da boca de fumo.", "question": "Caio e Dani respondem por qual crime?", "steps": ["O art. 36 pune quem financia ou custeia a prática dos crimes dos arts. 33, caput e § 1º, e 34. A pena é reclusão de 8 a 20 anos e 1.500 a 4.000 dias-multa.", "O art. 37 pune quem colabora, como informante, com grupo, organização ou associação destinados a esses crimes. A pena é reclusão de 2 a 6 anos e 300 a 700 dias-multa.", "Caio financia: art. 36. Dani avisa sobre a polícia, fazendo o papel de informante: art. 37."], "conclusion": "Caio responde pelo art. 36 (pena maior) e Dani pelo art. 37 (pena menor). O papel de cada um define o artigo.", "variation": {"scenario": "E se Dani, além de avisar, também vendesse a droga?", "answer": "Aí ele também se enquadra no art. 33 pela venda, além do art. 37 pela função de informante, conforme o caso."}, "pitfall": "Achar que só quem toca na droga responde. Financiar e avisar também são crimes autônomos, cada um com a sua pena.", "articles": ["Art. 36", "Art. 37"]}, {"id": "drog-6", "title": "Vender perto da escola e o dobro da facção", "scenario": "Rui vende drogas na porta de uma escola. Outro traficante, Téo, é integrante de uma facção e vende drogas como parte da atuação do grupo, nos termos do art. 2º da Lei 15.358.", "question": "Como a lei aumenta a pena de cada um?", "steps": ["O art. 40 prevê aumento de 1/6 a 2/3 para os crimes dos arts. 33 a 37 em hipóteses como proximidade de escolas, hospitais e presídios (inciso III) ou emprego de arma de fogo (inciso IV).", "Rui vende perto de escola: incide a causa de aumento do art. 40, III.", "O art. 40-A (incluído pela Lei 15.358/2026) manda aplicar em dobro as penas dos arts. 33 a 37 quando o autor é integrante de organização ultraviolenta, grupo paramilitar ou milícia, no contexto do art. 2º da Lei 15.358. Se houver arma de fogo, aplica-se concurso material (art. 69 do CP)."], "conclusion": "Rui sofre o aumento de 1/6 a 2/3 do art. 40. Téo sofre a pena em dobro do art. 40-A, porque age como integrante da facção.", "variation": {"scenario": "E se Téo vendesse drogas por conta própria, sem ligação com o grupo?", "answer": "O art. 40-A exige o contexto do art. 2º da Lei 15.358. Sem esse contexto, o dobro não se aplica."}, "pitfall": "Confundir o aumento do art. 40 (fração de 1/6 a 2/3) com o dobro do art. 40-A (só para integrante de facção, grupo paramilitar ou milícia).", "articles": ["Art. 40", "Art. 40-A"]}]}$json$::jsonb,
  $json$[{"title": "Lei 11.343/2006 — texto oficial (arts. 28, 33 a 37, 40 e 40-A)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11343.htm", "checked_at": "2026-10-08T02:42:22Z"}]$json$::jsonb,
  '2026-10-08T02:42:22Z',
  'under_review'
from public.study_materials m
where m.slug in ('legislacao-drogas-revisao', 'legislacao-penal-especial-drogas')
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar o Estatuto do Desarmamento", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Onde está a arma e como é usada? (posse × porte × disparo)", "A arma é de uso permitido, restrito ou proibido? (arts. 12, 14 e 16)", "É comércio ou tráfico? (arts. 17 e 18)", "Há ligação com drogas? (aumento de 2/3 do art. 21-A)"]}], "cases": [{"id": "arm-1", "title": "Em casa é posse; na rua é porte", "scenario": "Paulo guarda um revólver de uso permitido em casa, sem o registro exigido. Ricardo anda com outro revólver de uso permitido na cintura, sem autorização.", "question": "Os dois cometem o mesmo crime?", "steps": ["O art. 12 trata de possuir ou manter sob guarda arma de uso permitido, em desacordo com a lei, no interior da residência ou no local de trabalho. A pena é detenção de 1 a 3 anos e multa.", "O art. 14 trata de portar, deter, adquirir, transportar etc. arma de uso permitido sem autorização. A pena é reclusão de 2 a 4 anos e multa.", "Paulo tem a arma dentro de casa: art. 12. Ricardo anda com ela na rua: art. 14."], "conclusion": "Crimes diferentes: Paulo responde pelo art. 12 (posse irregular) e Ricardo pelo art. 14 (porte ilegal), com pena maior.", "variation": {"scenario": "E se a arma de Ricardo estivesse registrada em nome dele?", "answer": "O parágrafo único do art. 14 diz que o crime é inafiançável, salvo quando a arma é registrada em nome do agente. O registro afeta a fiança, mas o porte continua sem autorização."}, "pitfall": "Tratar \"ter arma\" e \"andar com arma\" como a mesma coisa. O lugar e a conduta mudam o artigo e a pena.", "articles": ["Art. 12", "Art. 14"]}, {"id": "arm-2", "title": "Uso permitido, restrito e proibido", "scenario": "Sérgio é flagrado com um fuzil em casa, sem autorização. Em outro caso, Tomás é flagrado com um revólver de uso permitido, também sem autorização.", "question": "O que muda de um caso para o outro?", "steps": ["O art. 16 trata de arma, acessório ou munição de uso restrito. A pena é reclusão de 3 a 6 anos e multa.", "O § 2º do art. 16 trata de arma de uso proibido: reclusão de 4 a 12 anos.", "Para uso permitido, os crimes são os do art. 12 (posse) e do art. 14 (porte), com penas menores."], "conclusion": "A categoria da arma muda o enquadramento: o fuzil de Sérgio, em tese, é de uso restrito (art. 16); o revólver de Tomás é de uso permitido (arts. 12 ou 14).", "variation": {"scenario": "E se a arma de Sérgio fosse de uso proibido?", "answer": "Aplica-se o § 2º do art. 16: reclusão de 4 a 12 anos."}, "pitfall": "Aplicar a pena do art. 12 para qualquer arma guardada em casa. Se a arma é de uso restrito ou proibido, o local não rebaixa o crime para o art. 12.", "articles": ["Art. 16"]}, {"id": "arm-3", "title": "Disparo para o alto na festa", "scenario": "Durante uma comemoração em rua de bairro, Hélio dispara a arma para o alto, em lugar habitado.", "question": "O fato é crime mesmo sem atingir ninguém?", "steps": ["O art. 15 pune quem dispara arma de fogo ou aciona munição em lugar habitado ou em suas adjacências, em via pública ou em direção a ela.", "A pena é reclusão de 2 a 4 anos e multa, e o crime é inafiançável.", "O tipo não exige ferir alguém: basta o disparo no local descrito, porque a lei protege a segurança coletiva."], "conclusion": "Sim. Disparar arma de fogo em lugar habitado ou em via pública já é o crime do art. 15, mesmo sem atingir ninguém.", "variation": {"scenario": "E se o disparo ocorresse em um sítio isolado, longe de casas e da via pública?", "answer": "O local deixa de ser \"habitado ou adjacências\" e a análise do tipo muda. Verifique o texto completo do art. 15 e as circunstâncias."}, "pitfall": "Achar que só há crime se alguém for ferido. O art. 15 pune o perigo gerado pelo disparo no lugar descrito.", "articles": ["Art. 15"]}, {"id": "arm-4", "title": "Consertar e vender armas na garagem", "scenario": "Sérgio conserta e revende armas de fogo na garagem de casa, sem autorização e sem loja. Um dos compradores era, na verdade, um policial disfarçado.", "question": "Sérgio pode responder por comércio ilegal de arma mesmo sem ter loja?", "steps": ["O art. 17 pune o comércio ilegal de arma de fogo com reclusão de 6 a 12 anos e multa (pena elevada pela Lei 13.964/2019).", "O § 1º equipara a atividade comercial qualquer forma de prestação de serviço irregular, mesmo em residência. Consertar e revender na garagem se encaixa.", "O § 2º aplica a mesma pena a quem vende ou entrega a agente policial disfarçado."], "conclusion": "Sim. Não é preciso ter loja: a atividade irregular em casa é equiparada a comércio, e vender a policial disfarçado não afasta o crime.", "variation": {"scenario": "E se Sérgio apenas vendesse uma arma antiga sua, uma única vez, a um amigo?", "answer": "O enquadramento depende do contexto: pode ser outro crime do Estatuto (como o art. 14), e não necessariamente o art. 17. A habitualidade e a atividade comercial pesam."}, "pitfall": "Achar que comércio ilegal exige estabelecimento. O § 1º do art. 17 cobre a atividade irregular mesmo em residência.", "articles": ["Art. 17"]}, {"id": "arm-5", "title": "Tráfico internacional de arma", "scenario": "Vânia traz pistolas de um país vizinho para o Brasil, sem autorização, para revendê-las.", "question": "Qual é a diferença entre o crime dela e o comércio ilegal comum?", "steps": ["O art. 18 trata do tráfico internacional de arma de fogo, acessório ou munição, com reclusão de 8 a 16 anos e multa (pena elevada pela Lei 13.964/2019).", "O art. 17, comércio ilegal comum, tem pena de 6 a 12 anos.", "O que diferencia os dois é o caráter internacional da operação (entrada ou saída do país sem autorização)."], "conclusion": "Vânia responde pelo art. 18, com pena maior que a do art. 17, por causa do caráter internacional.", "variation": {"scenario": "E se as pistolas fossem compradas e vendidas só dentro do Brasil?", "answer": "Sem o elemento internacional, o enquadramento passa a ser o do art. 17 (comércio ilegal)."}, "pitfall": "Confundir os dois artigos. O que muda é a transnacionalidade: comércio ilegal (art. 17) × tráfico internacional (art. 18).", "articles": ["Art. 18"]}, {"id": "arm-6", "title": "O aumento de dois terços: só para alguns artigos", "scenario": "Davi vende drogas e leva uma pistola de uso permitido, sem autorização, para garantir o sucesso da venda. Em outro caso, Eva dispara uma arma em via pública durante uma briga de rua, sem ligação com drogas.", "question": "O aumento de 2/3 do art. 21-A vale para os dois?", "steps": ["O art. 21-A (incluído pela Lei 15.358/2026) diz que, nos crimes dos arts. 12, 14 e 16, a pena é aumentada de 2/3 se o crime for praticado em concurso com crime da Lei de Drogas, estiver diretamente ligado ao comércio ilícito de entorpecentes ou a arma tiver sido usada para assegurar o sucesso da mercancia.", "Davi porta a pistola (art. 14) e a usa para garantir a venda de drogas: o aumento se aplica.", "Eva responde pelo art. 15 (disparo), e o art. 21-A só cita os arts. 12, 14 e 16. Além disso, não há ligação com drogas."], "conclusion": "O aumento vale para Davi (art. 14 ligado ao tráfico) e não vale para Eva (art. 15, sem drogas).", "variation": {"scenario": "E se Davi guardasse um fuzil de uso restrito em casa para garantir a mercancia?", "answer": "O art. 16 está entre os artigos do art. 21-A, e o aumento de 2/3 também se aplica."}, "pitfall": "Aplicar o aumento a qualquer crime de arma. O art. 21-A vale só para os arts. 12, 14 e 16, e quando há ligação com drogas.", "articles": ["Art. 21-A", "Art. 14"]}]}$json$::jsonb,
  $json$[{"title": "Lei 10.826/2003 — texto oficial (arts. 12, 14 a 18 e 21-A)", "url": "https://www.planalto.gov.br/ccivil_03/leis/2003/l10.826.htm", "checked_at": "2026-10-08T02:42:22Z"}]$json$::jsonb,
  '2026-10-08T02:42:22Z',
  'under_review'
from public.study_materials m
where m.slug in ('legislacao-armas-revisao', 'legislacao-armas-posse-porte', 'legislacao-penal-especial-armas')
on conflict (material_slug, version) do nothing;

commit;
